 insert into public.departments(department_code,department_name) values('STG-BR','Staging Bounded Retry') on conflict ((lower(department_code))) do update set department_name=excluded.department_name returning id into d;
 insert into public.programs(department_id,program_code,program_name) values(d,'STG-BR','Staging Bounded Retry') on conflict (department_id,(lower(program_code))) do update set program_name=excluded.program_name returning id into p;
 insert into public.sections(program_id,section_name,year_level,academic_year,semester) values(p,'BR',1,'2099-2100','Bounded Retry') on conflict (program_id,(lower(section_name)),academic_year,semester) do update set year_level=excluded.year_level returning id into sec;
 insert into public.profiles(id,email,first_name,last_name,role,account_status,department_id,employee_id,student_id) values(ou,'plpass-bounded-retry-organizer@staging.invalid','Synthetic','Retry Organizer','organizer','active',d,'STG-BR-ORG',null) on conflict(id) do update set role='organizer',account_status='active',department_id=d;
 insert into public.organizers(profile_id,employee_id,department_id,organization_name,position,organizer_status) values(ou,'STG-BR-ORG',d,'PLPass Staging','Retry Organizer','active') on conflict(profile_id) do update set organizer_status='active' returning id into org;
 insert into public.profiles(id,email,first_name,last_name,role,account_status,department_id,employee_id,student_id) values(su,'plpass-bounded-retry-student@staging.invalid','Synthetic','Retry Student','student','active',d,null,'STG-BR-1') on conflict(id) do update set role='student',account_status='active',department_id=d,student_id='STG-BR-1';
 insert into public.students(profile_id,student_id,program_id,department_id,section_id,year_level,student_status) values(su,'STG-BR-1',p,d,sec,1,'enrolled') on conflict(profile_id) do update set student_status='enrolled' returning id into stu;
 insert into public.event_categories(category_name) values('Staging Bounded Retry') on conflict ((lower(category_name))) do update set category_name=excluded.category_name returning id into cat;
 insert into public.events(event_code,organizer_id,department_id,category_id,title,description,venue,starts_at,ends_at,event_status,approval_status) values('STG-BOUNDED-RETRY',org,d,cat,'Staging Bounded Retry','Synthetic only','Staging Test Room',day at time zone 'Asia/Manila',(day+interval '23 hours 59 minutes') at time zone 'Asia/Manila','ongoing','approved') on conflict ((lower(event_code))) do update set organizer_id=org,department_id=d,category_id=cat,event_status='ongoing',approval_status='approved' returning id into ev;
 insert into public.event_participants(event_id,student_id,participant_status) values(ev,stu,'confirmed') on conflict(event_id,student_id) do update set participant_status='confirmed';
