-- Staging-only fixture. Create confirmed Auth users first:
-- plpass-bounded-retry-organizer@staging.invalid and plpass-bounded-retry-student@staging.invalid
do $$ declare ou uuid; su uuid; d uuid; p uuid; sec uuid; cat uuid; org uuid; stu uuid; ev uuid; day timestamp;
begin
 select id into ou from auth.users where email='plpass-bounded-retry-organizer@staging.invalid'; select id into su from auth.users where email='plpass-bounded-retry-student@staging.invalid'; if ou is null or su is null then raise exception 'Create the two synthetic Auth users first.'; end if; day:=date_trunc('day',now() at time zone 'Asia/Manila');
 delete from public.event_sessions where event_id=ev; insert into public.event_sessions(event_id,session_name,venue,mode,session_status,scheduled_start,scheduled_end,actual_start,attendance_window_start_at,attendance_window_end_at,created_by) values(ev,'Retry Attendance','Staging Test Room','f2f','ongoing',day at time zone 'Asia/Manila',(day+interval '23 hours 59 minutes') at time zone 'Asia/Manila',now(),now(),(day+interval '23 hours 59 minutes') at time zone 'Asia/Manila',ou);
end $$;
